export function renderSVGMap(countryCode = 'SN', regionScoresMap = {}) {
  const mapData = countryMapPaths[countryCode] || countryMapPaths.SN;

  function getPerfClass(score) {
    if (score === null || score === undefined || score <= 0) return "map-region-unrated";
    if (score >= 4.5) return "map-region-very-good";
    if (score >= 4.0) return "map-region-high";
    if (score >= 3.0) return "map-region-med";
    if (score >= 2.0) return "map-region-low";
    return "map-region-critical";
  }

  const pathsHTML = mapData.regions.map(r => {
    const realScore = (regionScoresMap && regionScoresMap[r.id] !== undefined && regionScoresMap[r.id] !== null) ? regionScoresMap[r.id] : null;
    const displayScore = realScore !== null && realScore > 0 ? `${realScore.toFixed(1)} / 5.0` : "Pas encore noté";


    return `
      <path 
        id="map-region-${r.id}"
        data-id="${r.id}"
        data-name="${r.name}"
        data-score="${displayScore}"
        d="${r.d}" 
        class="map-region-path ${getPerfClass(realScore)}" 
      />
    `;
  }).join('');

  return `
    <div class="map-container" id="interactive-country-map-wrapper">
      <svg class="senegal-map-svg" viewBox="${mapData.viewBox}">
        <g id="country-regions-group">
          ${pathsHTML}
        </g>
      </svg>
      <div id="map-tooltip" class="map-tooltip"></div>
    </div>
  `;
}


export function attachMapEvents(containerEl, onSelectCallback) {
  const tooltip = containerEl.querySelector('#map-tooltip');
  if (!tooltip) return;

  const paths = containerEl.querySelectorAll('.map-region-path');

  let lastTappedPath = null;

  paths.forEach(p => {
    const name = p.getAttribute('data-name');
    const scoreStr = p.getAttribute('data-score'); // e.g. "3.2 / 5.0" or "Pas encore noté"

    function showTooltip(x, y) {
      tooltip.innerHTML = `<strong>${name}</strong><br>${scoreStr}`;
      tooltip.style.display = 'block';
      tooltip.style.left = (x + 10) + 'px';
      tooltip.style.top = (y - 32) + 'px';
    }

    // Mouse events (desktop)
    p.addEventListener('mouseenter', (e) => {
      const wrapper = containerEl.querySelector('#interactive-country-map-wrapper');
      const rect = wrapper ? wrapper.getBoundingClientRect() : { left: 0, top: 0 };
      showTooltip(e.clientX - rect.left, e.clientY - rect.top);
    });

    p.addEventListener('mousemove', (e) => {
      const wrapper = containerEl.querySelector('#interactive-country-map-wrapper');
      if (!wrapper) return;
      const rect = wrapper.getBoundingClientRect();
      tooltip.style.left = (e.clientX - rect.left + 10) + 'px';
      tooltip.style.top = (e.clientY - rect.top - 32) + 'px';
    });

    p.addEventListener('mouseleave', () => {
      tooltip.style.display = 'none';
    });

    // Touch/click events (mobile) — tap to show tooltip, tap again or elsewhere to hide
    p.addEventListener('click', (e) => {
      const id = p.getAttribute('data-id');
      if (onSelectCallback) onSelectCallback(id, name);

      if (lastTappedPath === p) {
        // Second tap on same region — hide tooltip
        tooltip.style.display = 'none';
        lastTappedPath = null;
      } else {
        const wrapper = containerEl.querySelector('#interactive-country-map-wrapper');
        const rect = wrapper ? wrapper.getBoundingClientRect() : { left: 0, top: 0 };
        const svgRect = p.closest('svg') ? p.closest('svg').getBoundingClientRect() : rect;
        // Use touch position or click position relative to wrapper
        const clientX = e.clientX || (e.touches && e.touches[0] ? e.touches[0].clientX : svgRect.left + svgRect.width / 2);
        const clientY = e.clientY || (e.touches && e.touches[0] ? e.touches[0].clientY : svgRect.top + svgRect.height / 2);
        showTooltip(clientX - rect.left, clientY - rect.top);
        lastTappedPath = p;
      }
    });
  });

  // Tap on map background = hide tooltip
  const wrapper = containerEl.querySelector('#interactive-country-map-wrapper');
  if (wrapper) {
    wrapper.addEventListener('click', (e) => {
      if (!e.target.classList.contains('map-region-path')) {
        tooltip.style.display = 'none';
        lastTappedPath = null;
      }
    });
  }
}

